from pathlib import Path
import json,re
from html import escape as e
r=Path('dist');catalog=json.loads((r/'content/hadith/catalog.json').read_text());home=(r/'index.html').read_text();header=re.search(r'<header class="site-header">.*?</dialog>',home,re.S)[0];footer=re.search(r'<footer class="site-footer">.*?</footer>',home,re.S)[0]
AR={'bukhari':'صحيح البخاري','muslim':'صحيح مسلم','abudawud':'سنن أبي داود','tirmidhi':'جامع الترمذي','nasai':'سنن النسائي','ibnmajah':'سنن ابن ماجه','malik':'موطأ مالك','nawawi':'الأربعون النووية','qudsi':'الأحاديث القدسية','dehlawi':'أربعون حديثًا للدهلوي'}
item='<a href="/hadiths.html"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 3h14v18l-7-4-7 4V3zM8 7h8M8 11h6"/></svg><span>Hadith library<small>Collections, books and individual reports</small></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-5-5 5 5-5 5"/></svg></a>'
def links(s):
 def nav(m):
  text=m[0]
  if 'href="/hadiths.html"' not in text:text=text.replace('</nav>',item+'</nav>')
  return text
 s=re.sub(r'<nav id="site-navigation".*?</nav>',nav,s,flags=re.S)
 s=s.replace('<a href="/about.html">About Al Furqan</a></nav>','<a href="/hadiths.html">Hadith library</a><a href="/about.html">About Al Furqan</a></nav>') if '<a href="/hadiths.html">Hadith library</a>' not in s else s
 return s
header=links(header);footer=links(footer)
for p in r.rglob('*.html'):p.write_text(links(p.read_text()))
boot='<script defer src="/vendor/supabase-2.118.0.js"></script><script defer src="/auth-config.js"></script><script defer src="/auth-client.js"></script><script defer src="/site-language.js?v=20261030-reading1"></script><script defer src="/navigation.js?v=20261029-site-language1"></script>'
def page(name,title,description,body,mode='',collection=''):
 p=r/name;p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(f'<!doctype html><html lang="en"><head><script src="/theme.js?v=20261029-theme1"></script><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description)}"><title>{e(title)} · Al Furqan</title><link rel="icon" href="/favicon.ico?v=2" sizes="any"><link rel="icon" type="image/svg+xml" href="/favicon.svg?v=2"><link rel="apple-touch-icon" href="/apple-touch-icon.png?v=2"><link rel="stylesheet" href="/hadith.css"><link rel="stylesheet" href="/footer.css?v=20261029-footer2"><link rel="stylesheet" href="/branding.css"><link rel="stylesheet" href="/navigation.css?v=20261029-theme1"><link rel="stylesheet" href="/site-language.css?v=20261029-site-language1">{boot}<script type="module" src="/hadith.js"></script><link rel="stylesheet" href="/theme.css?v=20261029-theme1"></head><body id="top" data-hadith-view="{mode}" data-collection="{collection}">{header}{body}{footer}</body></html>')
def card(c):return f'<a class="hadith-collection-card" href="/hadith/{c["id"]}.html"><span class="hadith-card-arabic" lang="ar" dir="rtl">{AR[c["id"]]}</span><span class="hadith-eyebrow">HADITH COLLECTION</span><h3>{e(c["name"])}</h3><p>{c["readable_count"]:,} entries with text<br>{len(c["books"])} books &amp; source groups</p><span class="hadith-card-action">Explore collection <span aria-hidden="true">↗</span></span></a>'
options=''.join(f'<option value="{c["id"]}">{e(c["name"])}</option>' for c in catalog['collections'])
coverage=f'''<details class="hadith-coverage"><summary>About the library, numbering and sources</summary><div><p>This library indexes {catalog['total']:,} numbered source entries across 10 collections. {catalog['readable_total']:,} have Arabic and/or English text; {catalog['total']-catalog['readable_total']:,} have neither in these editions. Repeated narrations and versions are counted separately. This is the coverage of the available dataset, not a claim to contain every hadith in existence.</p><p>Some source book assignments are missing. Those entries remain within their collection and are labelled “Book not assigned in source”. Source numbering, including decimal identifiers, is preserved and can differ from other editions.</p><p>Texts and grading are supplied by the Hadith API dataset. Each report is loaded from a fixed source version and displayed here, without generated translations or grading. Individual grades are displayed where supplied; the presence of a report in a collection does not itself provide an individual grading.</p><p>Available language editions vary by collection. Translator or author attribution is shown as supplied by the dataset. Arabic and English coverage was checked; additional language editions are loaded on request and checked against the report reference.</p><a href="https://github.com/fawazahmed0/hadith-api/tree/{catalog['revision']}" target="_blank" rel="noopener">Dataset and source revision ↗</a><a href="/hadith-LICENSE.txt">Dataset licence</a></div></details>'''
page('hadiths.html','Hadith library','Browse ten Hadith collections, their books and individual numbered reports inside Al Furqan.',f'''<main class="hadith-shell"><section class="hadith-library-hero"><div><span class="hadith-eyebrow">THE PROPHETIC TRADITION</span><h1>A library for<br><em>closer study.</em></h1><p>Explore collections, browse their books, and open each narration on its own page. Read the Arabic text alongside available translations and the source’s grading.</p></div><div class="hadith-hero-stat"><strong>{catalog['readable_total']:,}</strong><span>entries with Arabic and/or English text</span><small>10 COLLECTIONS · SOURCE REFERENCES INCLUDED</small></div></section><form class="hadith-jump" id="hadith-jump"><div><span class="hadith-eyebrow">HAVE A REFERENCE?</span><h2>Go straight to a hadith.</h2></div><label>Collection<select id="jump-collection">{options}</select></label><label>Source hadith number<input id="jump-number" inputmode="decimal" required maxlength="20" placeholder="e.g. 1"></label><button class="hadith-primary" type="submit">Open hadith →</button><p id="jump-status" class="hadith-status" role="status" hidden></p></form><section class="hadith-catalog" aria-labelledby="hadith-collections-title"><div class="hadith-section-heading"><div><span class="hadith-eyebrow">BROWSE THE COLLECTIONS</span><h2 id="hadith-collections-title">Begin with a collection.</h2></div><span>10 collections</span></div><div class="hadith-collection-grid">{''.join(card(c) for c in catalog['collections'])}</div></section>{coverage}</main>''','library')
for c in catalog['collections']:
 books=''.join(f'<a class="hadith-book-row" data-book-row href="/hadith-book.html?collection={c["id"]}&amp;book={b["id"]}"><span class="hadith-book-number">{b["id"]}</span><span><strong>{e(b["title"] or "Book not assigned in source")}</strong><small>{b["count"]:,} numbered entries</small></span><span aria-hidden="true">↗</span></a>' for b in c['books'])
 page('hadith/'+c['id']+'.html',c['name'],'Browse the books and numbered reports in '+c['name']+'.',f'''<main class="hadith-shell"><nav class="hadith-breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="/hadiths.html">Hadith library</a><span>/</span><span aria-current="page">{e(c['name'])}</span></nav><section class="hadith-collection-heading"><span class="hadith-eyebrow">HADITH COLLECTION</span><h1>{e(c['name'])}</h1><p class="hadith-collection-arabic" lang="ar" dir="rtl">{AR[c['id']]}</p><div class="hadith-facts"><span>{c['readable_count']:,} entries with text</span><span>{c['count']:,} numbered source entries</span><span>{len(c['books'])} books &amp; source groups</span></div></section><div class="hadith-book-heading"><h2>Books in this edition</h2><label>Find a book<input type="search" id="book-query" placeholder="Search book titles…" maxlength="120"></label></div><div class="hadith-book-grid">{books}</div><p class="hadith-status" id="book-empty" hidden>No book titles match your search.</p>{coverage}</main>''','collection',c['id'])
common='''<p class="hadith-status" id="hadith-status" role="status">Loading the source index…</p><button class="hadith-secondary" id="hadith-retry" type="button" hidden>Try again</button>'''
page('hadith-book.html','Browse a Hadith book','Read and search the numbered reports in a selected Hadith book.',f'''<main class="hadith-shell"><nav class="hadith-breadcrumb" aria-label="Breadcrumb"><a href="/hadiths.html">Hadith library</a><span>/</span><a id="book-collection-link" href="/hadiths.html">Collection</a><span>/</span><span id="book-crumb" aria-current="page">Book</span></nav><section class="hadith-book-page-heading"><span class="hadith-eyebrow" id="book-collection-name">HADITH COLLECTION</span><h1 id="book-page-title">Browse a book</h1><p id="book-page-count"></p></section>{common}<section id="book-content" hidden><form class="hadith-book-tools" id="book-search"><label>Search within this book<input type="search" id="book-search-query" placeholder="A word or phrase in the selected language" maxlength="160"></label><label>Text edition<select id="book-language"></select></label><button class="hadith-primary" type="submit">Search book</button></form><p class="hadith-search-note">Search checks the published text of this book only. Open a report to read its Arabic text, available translations and source grades.</p><div id="hadith-entries" class="hadith-entry-list"></div><div class="hadith-pagination"><span id="hadith-page-summary"></span><div><button class="hadith-secondary" id="hadith-prev-page" type="button">← Previous</button><button class="hadith-secondary" id="hadith-next-page" type="button">Next →</button></div></div></section></main>''','book')
page('hadith.html','Read a Hadith','Read an individual Hadith report with Arabic text, published translation, grading and its source reference.',f'''<main class="hadith-shell hadith-reader-shell"><nav class="hadith-breadcrumb" aria-label="Breadcrumb"><a href="/hadiths.html">Hadith library</a><span>/</span><a id="reader-collection-link" href="/hadiths.html">Collection</a><span>/</span><a id="reader-book-link" href="/hadiths.html">Book</a></nav><div class="hadith-reader-heading"><div><span class="hadith-eyebrow" id="reader-collection-name">HADITH COLLECTION</span><h1 id="reader-title">Read a hadith.</h1><p id="reader-book-name"></p></div><a class="hadith-secondary" id="reader-browse" href="/hadiths.html">Browse the collection</a></div>{common}<section id="reader-content" hidden><div class="hadith-reader-tools"><label>Translation<select id="reader-language"></select></label><div class="hadith-reader-buttons"><button class="hadith-secondary" id="hadith-size-down" type="button" aria-label="Decrease Arabic text size">A−</button><button class="hadith-secondary" id="hadith-size-up" type="button" aria-label="Increase Arabic text size">A+</button><button class="hadith-secondary" id="hadith-copy" type="button">Copy reference</button></div></div><p id="hadith-copy-status" class="hadith-status" role="status" hidden></p><article class="hadith-text-card"><div class="hadith-text-label">ARABIC TEXT</div><p id="reader-arabic" class="hadith-arabic" lang="ar" dir="rtl"></p><p id="reader-arabic-error" class="hadith-status" hidden></p><div id="reader-translated-block"><div class="hadith-text-label" id="reader-translation-label">PUBLISHED TRANSLATION</div><p id="reader-translation" class="hadith-translation"></p><p id="reader-translation-error" class="hadith-status" hidden></p><p class="hadith-edition-credit" id="reader-edition-credit"></p></div></article><section class="hadith-reference-panel"><div><span class="hadith-eyebrow">REFERENCE IN THIS DATASET</span><dl id="reader-reference"></dl></div><div><span class="hadith-eyebrow">GRADES REPORTED BY THE SOURCE</span><ul id="reader-grades"></ul><p class="hadith-search-note">Grading is reproduced from the source with the evaluator’s name. No new grading is assigned by Al Furqan.</p></div></section><details class="hadith-source-details"><summary>Edition and source information</summary><p id="reader-source-description"></p><p>Texts appear as supplied by the source, including reported variants and punctuation. Numbering can differ between editions. Read a report with its book context and published scholarly explanations.</p><a id="reader-source-arabic" target="_blank" rel="noopener">Arabic edition source ↗</a><a id="reader-source-translation" target="_blank" rel="noopener">Translation edition source ↗</a><a href="/hadiths.html">Library coverage and source details</a></details><div class="hadith-reader-pagination"><a class="hadith-secondary" id="reader-prev">← Previous hadith</a><a class="hadith-secondary" id="reader-next">Next hadith →</a></div></section></main>''','reader')
# Add a compact library introduction to the home page.
home=(r/'index.html').read_text();feature=f'''<section class="home-hadith" id="hadith-library" aria-labelledby="home-hadith-title"><div class="shell"><div class="hadith-section-heading"><div><span class="hadith-eyebrow">THE HADITH LIBRARY</span><h2 id="home-hadith-title">Explore the Prophetic tradition.</h2><p>Browse 10 collections, their books and individual narrations. Arabic text, available translations and source references stay close at hand.</p></div><a class="hadith-secondary" href="/hadiths.html">All collections →</a></div><div class="hadith-home-grid">{''.join(card(c) for c in catalog['collections'][:3])}</div><p class="hadith-home-note">{catalog['readable_total']:,} entries with Arabic and/or English text. Source numbering and repeated narrations are preserved.</p></div></section>'''
if 'id="hadith-library"' not in home:home=home.replace('    <section class="about"',feature+'\n    <section class="about"')
if '/hadith.css' not in home:home=home.replace('<link rel="stylesheet" href="/theme.css?v=20261029-theme1"></head>','<link rel="stylesheet" href="/hadith.css"><link rel="stylesheet" href="/theme.css?v=20261029-theme1"></head>')
(r/'index.html').write_text(home)

